import numpy as np
from scipy import sparse
class Solver:
 def solve(self,p,**kw):
  A=p['matrix'];n=A.shape[0]
  w,V=sparse.linalg.eigs(A,k=5,v0=np.ones(n,dtype=A.dtype),ncv=20,tol=1e-5,maxiter=n*200)
  # Group conjugates by their (identical) modulus, retaining real roots.
  ids=sorted(range(5),key=lambda i:-abs(w[i])); out=[]; pair=0; i=0
  while i<len(ids):
   j=ids[i]; z=w[j]
   if abs(z.imag)<1e-9:
    out.append(V[:,j]);i+=1;continue
   same=[]
   while i<len(ids) and abs(abs(w[ids[i]])-abs(z)) < 1e-7*max(1,abs(z)):
    same.append(ids[i]);i+=1
   pos=next((q for q in same if w[q].imag>0),same[0])
   x=V[:,pos] if w[pos].imag>0 else np.conj(V[:,pos])
   if len(same)>=2:
    if pair==0: out.extend([np.conj(x),x])
    else: out.extend([x,np.conj(x)])
    pair+=1
   else: out.append(x)
  return out[:5]
